I've attached a self contained code example and I'm using Rserve-0.6 and its
associated Java client


import org.rosuda.REngine.*;
import org.rosuda.REngine.Rserve.*;
import java.util.ArrayList;

public class foo {
    public static void main(String[] args){
    try{
        RConnection rc = new RConnection("127.0.0.1",8888);
        ArrayList<REXP> rexpArray = new ArrayList<REXP>();
        for(int i=0;i<10;i++){
        rc.assign("x",new REXPInteger(i));
        REXP v = rc.eval("serialize(x,connection=NULL)");
        rexpArray.add(v);
        }
        RList rlist = new RList(rexpArray);;
        REXPGenericVector rl = new REXPGenericVector(rlist);
        rc.assign("red.value",rl);
    }catch(RserveException e){
        e.printStackTrace();
    }
    }
}











Saptarshi Guha


